package com.primehr.succession.domain;
import com.primehr.integration.administrative.AdministrativePositionTarget; import com.primehr.positionprofile.domain.PositionTargetType; import com.primehr.shared.exception.IllegalLifecycleTransitionException; import org.junit.jupiter.api.Test; import java.time.*; import static org.assertj.core.api.Assertions.*;
class SuccessionPlanningDomainTest {
 private static AdministrativePositionTarget target(PositionTargetType type,long id,String fingerprint){return new AdministrativePositionTarget(type,id,id+100,"Position "+id,null,null,type==PositionTargetType.PLANTILLA?id:null,type==PositionTargetType.PLANTILLA?"Plantilla "+id:null,fingerprint,Instant.parse("2026-01-01T00:00:00Z"));}
 @Test void careerPathRejectsSelfLinkAndPublishedFamilyIsImmutable(){assertThatThrownBy(()->new SuccessionCareerPathLink("A","V",target(PositionTargetType.JOB_POSITION,1,"a"),target(PositionTargetType.JOB_POSITION,1,"a"),SuccessionCareerPathLink.RelationshipType.VERTICAL,"Move",1)).isInstanceOf(IllegalArgumentException.class);var family=new SuccessionCareerFamilyVersion("A","F",1,null,"Family",null,"CSC rules","Guidance");family.publish(LocalDate.of(2026,1,1),null,"admin",Instant.now());assertThatThrownBy(()->family.update("Changed",null,"Basis","Guide")).isInstanceOf(IllegalLifecycleTransitionException.class);}
 @Test void designationRequiresHumanSeparationAndValidLifecycle(){var d=new SuccessionCriticalPositionDesignation("A",target(PositionTargetType.PLANTILLA,2,"fp"),"framework",1,"framework:1:1","charter","Critical Head","Continuity risk",LocalDate.of(2026,1,1),LocalDate.of(2026,7,1));d.submit("maker",Instant.now());assertThatThrownBy(()->d.approve("maker","Approved",LocalDate.of(2026,1,1),null,Instant.now())).isInstanceOf(IllegalArgumentException.class);d.approve("committee-member","Approved after review",LocalDate.of(2026,1,1),null,Instant.now());assertThat(d.getStatus()).isEqualTo(SuccessionCriticalPositionDesignation.Status.APPROVED);assertThatThrownBy(()->d.update("Changed","Changed",LocalDate.now(),LocalDate.now())).isInstanceOf(IllegalLifecycleTransitionException.class);}
}
